```python
def prime_factors(n):
    factors = []
    for divisor in [2, 3]:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
    for divisor in range(5, int(n ** 0.5) + 1, 6):
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        while n % (divisor + 2) == 0:
            factors.append(divisor + 2)
            n //= (divisor + 2)
    if n > 1:
        factors.append(n)
    return factors

