    output_seq = []
    for i in range(len(input_seq)):
        for j in range(i+1, len(input_seq)):
            substring = common_substring(input_seq[i], input_seq[j])
            if len(substring) > len(longest_substring):
                longest_substring = substring
                output_seq = [input_seq[i], input_seq[j]]
    return output_seq

def common_substring(str1, str2):
    longest = ""
    for i in range(len(str1)):
        for j in range(len(str2)):
            pos = 0
            while str1[i + pos] == str2[j + pos]:
                pos += 1
                if (i + pos >= len(str1)) or (j + pos >= len(str2)):
                    break
            if pos > len(longest):
                longest = str1[i:i + pos]
    return longest

