def find_max_min(lst):
    if len(lst) == 1:
        return lst[0], lst[0]

    elif len(lst) == 2:
        return max(lst), min(lst)

    mid = len(lst)//2
    left_max, left_min = find_max_min(lst[:mid])
    right_max, right_min = find_max_min(lst[mid:])

    return max(left_max, right_max), min(left_min, right_min)

