# Function to calculate the maximum value 
def knapSack(weights, values, max_weight): 
    n = len(weights)

    # Array with one extra item 
    table = [[0 for x in range(max_weight + 1)] for x in range(n + 1)] 

    # Build table memonizing the subproblems 
    for i in range(n + 1): 
        for w in range(max_weight + 1): 
            if i == 0 or w == 0: 
                table[i][w] = 0
            elif weights[i-1] <= w: 
                table[i][w] = max(values[i-1] + table[i-1][w-weights[i-1]], table[i-1][w]) 
            else: 
                table[i][w] = table[i-1][w] 

    # Handles the case when there is no item in the knapsack 
    # Maximum value is 0 
    return table[n][max_weight]
```

