def levenshteinDistance(str1, str2):
 # base case 
 # if one of the strings is empty
 # then the Levenshtein distance will be equal
 # to the length of the other string
 if str1 == "":
 return len(str2)
 if str2 == "":
 return len(str1)

 # initialize the variables
 m = len(str1)
 n = len(str2)
 cost = 0

 # find the cost
 if str1[m-1] == str2[n-1]:
 cost = 0
 else:
 cost = 1

 # return the minimum of three possible operations
 return min(
 levenshteinDistance(str1[:-1], str2)+1, # delete
 levenshteinDistance(str1, str2[:-1])+1, # insert
 levenshteinDistance(str1[:-1], str2[:-1]) + cost # replace
 )

str1 = "kitten"
str2 = "sitting"

print(levenshteinDistance(str1, str2)) # 3
```

