def sudoku(board): 

    # Check if the board is full 
    if not any(None in sublist for sublist in board): 
        return True

    # Find empty cells 
    for i in range(len(board)): 
        for j in range(len(board[0])): 
            if board[i][j]==None: 
                for k in range(1,10): 
                    board[i][j]=k 
                    # Try to solve the board 
                    if sudoku(board): 
                        return True
                    # Backtrack and try with different  
                    # values 
                    board[i][j]=None 
    return False
