def binary_search(arr, value):
  low = 0
  high = len(arr) - 1
  found = False

  while low <= high and not found:
    mid = low + (high - low) // 2
    if arr[mid] == value:
      found = True
    elif arr[mid] < value:
      low = mid + 1
    else:
      high = mid - 1

  if found:
    return mid
  else:
    return -1
