def word_frequency(text):
    # Create a dictionary to store word frequencies
    freq = {}

    # Split the text into words
    words = text.split()

    # Iterate through every word and add it to the dictionary
    for word in words:
        if word in freq:
            freq[word] += 1
        else:
            freq[word] = 1

    # Return the dictionary
    return freq
