```python
def edit_distance(string1, string2):
    m = len(string1)
    n = len(string2)
    dp = [[0 for _ in range(n+1)] for _ in range(m+1)]

    for i in range(m+1):
        for j in range(n+1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif string1[i-1] == string2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i][j-1], 
                        dp[i-1][j], 
                        dp[i-1][j-1]) 
    return dp[m][n]
```

