def print_hollow_diamond(n):
    # top side
    for i in range(n):
        for j in range(n):
            if j == i or j == n-i-1:
                print('* ', end = '')
            else:
                print('  ', end = '')
        print() 

    # middle straight line
    for j in range(n):
        print('* ', end = '')
    print()

    # bottom side
    for i in range(n , 0 , -1):
        for j in range(n):
            if j == i - 1 or j == n-i:
                print('* ', end = '')
            else:
                print('  ', end = '')
