 n = len(string1)
 m = len(string2)

 LCS = [[0 for x in range(m+1)] for y in range(n+1)]

 for i in range(n):
 for j in range(m):
 if (string1[i] == string2[j]):
 LCS[i][j] = LCS[i-1][j-1] + 1
 else:
 LCS[i][j] = max(LCS[i-1][j], LCS[i][j-1])

#return the longest common sequence
 index = LCS[n][m]
